<script setup lang="ts">defineProps<{open:boolean;title:string;message:string;confirmLabel?:string}>();defineEmits(['confirm','close']);const {working}=useShowUp()</script>
<template><div v-if="open" class="dialog-backdrop" @click.self="!working && $emit('close')"><section class="dialog" role="alertdialog" aria-modal="true" :aria-label="title"><h2>{{ title }}</h2><p>{{ message }}</p><button class="danger" :disabled="!!working" @click="$emit('confirm')">{{ working || confirmLabel || 'Confirm' }}</button><button class="secondary" :disabled="!!working" @click="$emit('close')">Go back</button></section></div></template>
